#!/usr/bin/env node
// Bundle src/core (ES modules) into one classic script for the Symbiote:
// symbiote/taleforge.js, exposing window.TaleForge.
//
// Symbiotes are plain local web pages in TaleSpire's embedded Chromium; a
// classic <script> always loads there, ES module imports from the Symbiote
// folder may not. Each module is wrapped in its own function scope, so module
// internals never collide. Supported syntax (all src/core uses):
//   import { a, b as c } from './x.js';
//   export function / async function / class / const / let
//   export { a, b } from './x.js';
//
//   node scripts/bundle.js          write the bundle
//   node scripts/bundle.js --check  fail if the committed bundle is stale

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const coreDir = join(root, 'src/core');
const outFile = join(root, 'symbiote/taleforge.js');

const IMPORT_RE = /^import\s*\{([^}]*)\}\s*from\s*'\.\/([\w-]+)\.js';\s*$/gm;
const REEXPORT_RE = /^export\s*\{([^}]*)\}\s*from\s*'\.\/([\w-]+)\.js';\s*$/gm;
const DECL_RE = /^export\s+(async\s+function\s*\*?|function\s*\*?|class|const|let)\s*([A-Za-z_$][\w$]*)/gm;

function parseNames(list) {
  return list.split(',').map((s) => s.trim()).filter(Boolean).map((s) => {
    const m = /^([\w$]+)(?:\s+as\s+([\w$]+))?$/.exec(s);
    if (!m) throw new Error(`cannot parse import/export name "${s}"`);
    return { from: m[1], to: m[2] || m[1] };
  });
}

function loadModule(name) {
  const src = readFileSync(join(coreDir, `${name}.js`), 'utf8');
  const deps = new Set();
  const exports = [];
  let code = src.replace(IMPORT_RE, (_, list, dep) => {
    deps.add(dep);
    const names = parseNames(list).map((n) => (n.from === n.to ? n.from : `${n.from}: ${n.to}`));
    return `const { ${names.join(', ')} } = __m['${dep}'];`;
  });
  code = code.replace(REEXPORT_RE, (_, list, dep) => {
    deps.add(dep);
    const names = parseNames(list);
    for (const n of names) exports.push(n.to);
    return `const { ${names.map((n) => (n.from === n.to ? n.from : `${n.from}: ${n.to}`)).join(', ')} } = __m['${dep}'];`;
  });
  code = code.replace(DECL_RE, (_, kind, id) => {
    exports.push(id);
    return `${kind.replace(/\s+/g, ' ').replace(/ \*$/, '*')} ${id}`;
  });
  if (/^\s*(import|export)\b/m.test(code)) {
    const line = code.split('\n').find((l) => /^\s*(import|export)\b/.test(l));
    throw new Error(`${name}.js: unsupported module syntax: ${line.trim()}`);
  }
  return { name, deps: [...deps], exports, code };
}

function bundle() {
  const modules = new Map();
  const order = [];
  const visiting = new Set();
  const visit = (name) => {
    if (modules.has(name)) return;
    if (visiting.has(name)) throw new Error(`import cycle through ${name}.js`);
    visiting.add(name);
    const mod = loadModule(name);
    for (const d of mod.deps) visit(d);
    visiting.delete(name);
    modules.set(name, mod);
    order.push(mod);
  };
  visit('index');
  const pkg = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'));
  const parts = [
    `/* TaleForge ${pkg.version} -- AI board builder for TaleSpire.`,
    ' * GENERATED by scripts/bundle.js from src/core. Do not edit; run `npm run bundle`. */',
    '(function (global) {',
    "  'use strict';",
    '  const __m = {};',
  ];
  for (const mod of order) {
    parts.push(`  // ---- ${mod.name}.js ----`);
    parts.push(`  __m['${mod.name}'] = (function () {`);
    parts.push(mod.code.replace(/^(?=.)/gm, '    '));
    parts.push(`    return { ${mod.exports.join(', ')} };`);
    parts.push('  })();');
  }
  parts.push("  global.TaleForge = __m['index'];");
  parts.push("})(typeof window !== 'undefined' ? window : globalThis);");
  return parts.join('\n') + '\n';
}

const out = bundle();
if (process.argv.includes('--check')) {
  if (!existsSync(outFile) || readFileSync(outFile, 'utf8') !== out) {
    console.error('symbiote/taleforge.js is stale: run `npm run bundle`');
    process.exit(1);
  }
  console.log('bundle is up to date');
} else {
  writeFileSync(outFile, out);
  console.log(`wrote ${outFile} (${(out.length / 1024).toFixed(1)} KB)`);
}
